<script lang="ts">import { onMount } from 'svelte';import DemoSection from '../DemoSection.svelte';import { Upload,type UploadFile } from '$lib/registry/ui/upload';let files=$state<UploadFile[]>([]),states=$state<UploadFile[]>([]);let timer:ReturnType<typeof setInterval>|undefined;onMount(()=>{states=[{id:'queued',file:new File([''],'brief.pdf',{type:'application/pdf'}),status:'queued',progress:0},{id:'uploading',file:new File([''],'image.jpg',{type:'image/jpeg'}),status:'uploading',progress:62},{id:'done',file:new File([''],'archive.zip',{type:'application/zip'}),status:'done',progress:100},{id:'error',file:new File([''],'failed.txt',{type:'text/plain'}),status:'error',progress:35}]});$effect(()=>()=>timer&&clearInterval(timer));function simulate(added:UploadFile[]){files=files.map(f=>added.some(a=>a.id===f.id)?{...f,status:'uploading'}:f);if(timer)clearInterval(timer);timer=setInterval(()=>{files=files.map(f=>f.status==='uploading'?{...f,progress:Math.min(100,f.progress+10),status:f.progress>=90?'done':'uploading'}:f);if(!files.some(f=>f.status==='uploading')){clearInterval(timer);timer=undefined}},250)}</script>
<div class="page-heading"><p class="eyebrow">Component</p><h1>Upload File</h1><p>Select files and preview consumer-owned upload progress.</p></div>
<DemoSection title="Drop zone and progress" source={'<Upload bind:files />'}><Upload bind:files accept="image/*,.pdf" multiple maxSize={5000000} maxFiles={6} onFilesAdded={simulate}/></DemoSection>
<DemoSection title="States"><Upload files={states} label="Drop project assets" color="success" multiple/></DemoSection>
<DemoSection title="Source variants" source={'<Upload variant="glow" />'}><div class="upload-variants">{#each ['button','compact','dropzone','gallery','glow'] as variant}<Upload variant={variant as 'button'|'compact'|'dropzone'|'gallery'|'glow'} files={variant==='gallery'?states.slice(0,2):[]} label={`${variant} upload`} multiple/>{/each}</div></DemoSection>
<style>.upload-variants{display:grid;grid-template-columns:repeat(auto-fit,minmax(16rem,1fr));gap:1.5rem;width:100%}</style>
